export async function mountRoleGallery(container,{name,initialMode=null,gallery,resolveImage,onSelect,onUpload,onClose}){
  const doc=container.ownerDocument,win=doc.defaultView,root=doc.createElement('section');root.className='rg-window';root.setAttribute('role','dialog');root.setAttribute('aria-label',name+'的图库');
  const style=doc.createElement('style');style.textContent=`.rg-window{pointer-events:auto;position:absolute;inset:0;z-index:50;background:#17120ded;overflow:hidden;color:#654e34;font-family:"Songti SC",serif}.rg-panel{position:absolute;box-sizing:border-box;width:1000px;height:630px;transform-origin:top left;padding:30px 36px;background:linear-gradient(135deg,#f5e9d2,#e5d3ae);border:1px solid #a38a62;border-radius:7px;box-shadow:0 15px 60px #0007}.rg-panel header{display:flex;align-items:center;gap:24px;height:53px}.rg-panel h2{font-weight:500;font-size:29px;margin:0;flex:1}.rg-panel button{font:24px "Songti SC",serif;cursor:pointer;color:inherit;border:0;background:none;min-width:52px;min-height:46px}.rg-panel button[aria-pressed=true]{color:#9b6353;border-bottom:2px solid #aa7a61}.rg-slots{display:grid;grid-template-columns:repeat(4,1fr);grid-template-rows:repeat(2,205px);gap:16px;margin-top:28px}.rg-slot{position:relative;border:1px solid #b69a7380;border-radius:4px;padding:8px;background:#fff8e832;display:flex;flex-direction:column;gap:5px}.rg-slot img{height:156px;width:100%;object-fit:contain;cursor:pointer}.rg-slot .rg-empty{height:156px;display:flex;align-items:center;justify-content:center;font-size:23px;color:#b29b78;cursor:pointer}.rg-slot.active{border:2px solid #ac775b}.rg-bottom{display:flex;justify-content:space-between;align-items:center;font-size:20px}.rg-bottom button{font-size:21px;min-height:32px}.rg-error{font-size:22px;color:#9e5547;margin-top:13px}.rg-panel button:focus-visible{outline:2px solid #ab7859;outline-offset:2px}`;
  root.innerHTML='<div class="rg-panel"><header><h2></h2><button data-mode="portrait">胸像</button><button data-mode="standee">全身照</button><button data-mode="head">Q版头像</button><button class="rg-close" aria-label="关闭图库">×</button></header><div class="rg-slots"></div><input type="file" accept="image/png,image/jpeg,image/webp,image/gif" hidden><div class="rg-error" role="status"></div></div>';root.prepend(style);container.append(root);root.querySelector('h2').textContent=name;let current=await gallery(),mode=initialMode??current.mode,uploadSlot=0,destroyed=false,version=0;
  function fit(){const scale=Math.min(container.clientWidth/1060,container.clientHeight/680),panel=root.querySelector('.rg-panel');panel.style.transform=`scale(${scale})`;panel.style.left=`${(container.clientWidth-1000*scale)/2}px`;panel.style.top=`${(container.clientHeight-630*scale)/2}px`;}
  async function render(){const token=++version;current=await gallery(mode);if(destroyed||token!==version)return;root.querySelectorAll('[data-mode]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.mode===mode)));const list=root.querySelector('.rg-slots');list.replaceChildren();
    for(let i=0;i<8;i++){const file=current.files[i],card=doc.createElement('article');card.className='rg-slot'+(i===current.index?' active':'');let imageNode;
      if(file){imageNode=doc.createElement('img');imageNode.alt=name+' '+(mode==='portrait'?'胸像':mode==='head'?'Q版头像':'全身照')+' '+(i+1);const url=await resolveImage(file);if(destroyed||token!==version)return;imageNode.src=url??'';imageNode.addEventListener('click',async()=>{await onSelect(mode,i);await render();});}
      else{imageNode=doc.createElement('div');imageNode.className='rg-empty';imageNode.textContent='空存储位';imageNode.addEventListener('click',()=>choose(i));}
      const bottom=doc.createElement('div');bottom.className='rg-bottom';const label=doc.createElement('span');label.textContent='第'+(i+1)+'位';const replace=doc.createElement('button');replace.type='button';replace.textContent=file?'更换':'添加';replace.setAttribute('aria-label',(file?'更换':'添加')+(mode==='portrait'?'胸像':mode==='head'?'Q版头像':'全身照')+'第'+(i+1)+'位');replace.addEventListener('click',()=>choose(i));bottom.append(label,replace);card.append(imageNode,bottom);list.append(card);}
  }
  function choose(index){uploadSlot=index;root.querySelector('input').click();}
  root.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{mode=button.dataset.mode;void render();}));root.querySelector('.rg-close').addEventListener('click',onClose);root.querySelector('input').addEventListener('change',async e=>{const blob=e.target.files?.[0];if(!blob)return;const error=root.querySelector('.rg-error');error.textContent='';try{await onUpload(mode,uploadSlot,blob);await onSelect(mode,uploadSlot);await render();}catch(err){error.textContent=err.message;}e.target.value='';});root.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();onClose();}});
  fit();await render();win.addEventListener('resize',fit);return{root,destroy(){destroyed=true;version++;win.removeEventListener('resize',fit);root.remove();}};
}
